var e=1.618033988749,t=e/(1+e),n=1-t,r={id:`golden-grid`,title:`Golden Grid`,category:`pattern`,description:`Recursive golden ratio subdivision with animated proportions. Each cell's colour is derived from its proportional dimensions.`,version:`2.0.0`,canvas:{width:800,height:800,context:`p5`},parameters:[{group:`Subdivision`,params:[{key:`maxDepth`,type:`slider`,label:`Max Depth`,min:4,max:16,step:1,default:13},{key:`loopFrames`,type:`slider`,label:`Loop Frames`,min:60,max:720,step:60,default:360}]},{group:`Animation`,params:[{key:`hueSpeed`,type:`slider`,label:`Hue Speed`,min:0,max:10,step:.5,default:3},{key:`satSpeed`,type:`slider`,label:`Saturation Speed`,min:0,max:10,step:.5,default:2},{key:`lumSpeed`,type:`slider`,label:`Lightness Speed`,min:0,max:5,step:.5,default:1}]}],presets:[{name:`Classic`,values:{maxDepth:13,loopFrames:360,hueSpeed:3,satSpeed:2,lumSpeed:1}},{name:`Deep`,values:{maxDepth:16,loopFrames:720,hueSpeed:2,satSpeed:1,lumSpeed:.5}},{name:`Shallow`,values:{maxDepth:8,loopFrames:180,hueSpeed:5,satSpeed:3,lumSpeed:2}},{name:`Static`,values:{maxDepth:13,loopFrames:360,hueSpeed:0,satSpeed:0,lumSpeed:0}}],export:{png:!0,gif:!0,webm:!1},animation:{type:`loop`,get loopFrames(){return r._liveLoopFrames??360},defaultFps:60,canPrerender:!0,animatableParams:[`hueSpeed`,`satSpeed`,`lumSpeed`],sequencer:!0},infoSections:[{heading:`DESCRIPTION`,body:`Golden Grid recursively subdivides an 800×800 canvas using golden-ratio proportions. At each depth the split alternates vertical and horizontal. The split ratio oscillates sinusoidally between the two golden proportions (≈0.382 and ≈0.618), causing the grid to breathe. Each terminal cell is coloured from its accumulated width, height, and area proportions via HSL, producing a continuously shifting chromatic mosaic.`},{heading:`ALGORITHM`,body:`Constants: φ = 1.618…, P_BIG = φ/(1+φ) ≈ 0.618, P_SMALL = 1−P_BIG ≈ 0.382. Time: t = (frame % loopFrames) / loopFrames ∈ [0,1). Ratio (per frame, computed once): r = φ^sin(2πt), split = r/(1+r) ∈ [P_SMALL, P_BIG]. Subdivision (_subdivide): binary tree to maxDepth; even depth = vertical split, odd = horizontal; flipped alternates the larger-cell side; wProp/hProp accumulate the product of all split ratios to the node. Log-norm (_logNorm): logNorm(v, mn, mx) = (ln v − ln mn)/(ln mx − ln mn), mapping golden-ratio products to linear [0,1]. Bounds: wMax = P_BIG^⌈d/2⌉, wMin = P_SMALL^⌈d/2⌉ (symmetric for height), cached until maxDepth changes. Colour at terminal cell: H = (wNorm + t×hueSpeed) % 1 (sawtooth); S = 1 − |(hNorm + t×satSpeed)×2 % 2 − 1| (triangle wave); L = 1 − |(aNorm + t×lumSpeed)×2 % 2 − 1| (triangle wave on area proportion).`},{heading:`PARAMETERS`,body:`maxDepth (4–16, step 1, default 13): recursion depth; terminal cells = 2^maxDepth. Depth 13 → 8,192 cells; depth 16 → 65,536 cells (likely drops frames). loopFrames (60–720, step 60, default 360): loop period in frames at 60 fps; controls both the animation cycle length and export frame count. hueSpeed (0–10, step 0.5, default 3): speed of sawtooth hue cycle driven by cell width. satSpeed (0–10, step 0.5, default 2): speed of triangle-wave saturation cycle driven by cell height. lumSpeed (0–5, step 0.5, default 1): speed of triangle-wave lightness cycle driven by cell area.`},{heading:`PRESETS`,body:`Classic (depth 13, 360 frames, hue 3, sat 2, lum 1): balanced default. Deep (depth 16, 720 frames, slower speeds): dense fine-grained grid at the performance limit. Shallow (depth 8, 180 frames, faster speeds): coarse grid with rapid colour cycling. Static (depth 13, 360 frames, all speeds 0): frozen grid with no colour motion.`},{heading:`PERFORMANCE`,body:`Cost is O(2^maxDepth) rect calls per frame. Depth 13 (default): 8,192 calls ≈ 8–12 ms/frame. Depth 16: 65,536 calls — likely exceeds 16 ms. The split ratio is computed once per frame and passed into the tree, eliminating 65,534 redundant sin/pow calls at depth 16. Normalisation bounds are cached and recomputed only when maxDepth changes. Worker offload is not feasible (uses p5 canvas API directly).`},{heading:`ANIMATION`,body:`Type: loop. Period: loopFrames frames (default 360 at 60 fps = 6 s). Fully deterministic: same frame + params → same output. Eligible for GIF export. The animation.loopFrames property dynamically tracks params.loopFrames, so export frame count always matches the current slider value. Colour-speed params (hueSpeed, satSpeed, lumSpeed) are registered as animatable — the ANIMATE tab can interpolate them between sequencer checkpoints.`},{heading:`KNOWN LIMITATIONS`,body:`At maxDepth 16 frame drops are expected on most hardware. loopFrames doubles as both the colour-cycle driver and the export frame count; changing it alters both simultaneously. Canvas is fixed at 800×800; no user resize control is exposed.`},{heading:`REFERENCES`,body:`Golden ratio: φ = (1+√5)/2 ≈ 1.618. Colour model: HSL via p.colorMode(HSL, 1, 1, 1). Log-normalisation maps geometrically-distributed proportion products to a perceptually linear scale. Based on pulsing_recursive_grid sketch.`}],_logNorm(e,t,n){return(Math.log(e)-Math.log(t))/(Math.log(n)-Math.log(t))},_subdivide(e,t,n,r,i,a,o,s,c,l,u,d,f){if(a>=l.maxDepth){let a=s*c,o=this._logNorm(s,d.wMin,d.wMax),f=this._logNorm(c,d.hMin,d.hMax),p=this._logNorm(a,d.aMin,d.aMax),m=u%l.loopFrames/l.loopFrames,h=(o+m*l.hueSpeed)%1,g=1-Math.abs((f+m*l.satSpeed)*2%2-1),_=1-Math.abs((p+m*l.lumSpeed)*2%2-1);e.fill(h,g,_),e.rect(t,n,r,i);return}if(a%2==0){let p=r*f,m=r-p,h=o?t+m:t,g=o?t:t+p;this._subdivide(e,h,n,p,i,a+1,o,s*f,c,l,u,d,f),this._subdivide(e,g,n,m,i,a+1,!o,s*(1-f),c,l,u,d,f)}else{let p=i*f,m=i-p,h=o?n+m:n,g=o?n:n+p;this._subdivide(e,t,h,r,p,a+1,o,s,c*f,l,u,d,f),this._subdivide(e,t,g,r,m,a+1,!o,s,c*(1-f),l,u,d,f)}},p5Setup(e,t){e.colorMode(e.HSL,1,1,1),e.noStroke(),e.noSmooth(),e.noLoop()},p5Draw(i,a,o){if(r._liveLoopFrames=a.loopFrames,this._lastMaxDepth!==a.maxDepth){this._lastMaxDepth=a.maxDepth;let e=Math.ceil(a.maxDepth/2),r=Math.floor(a.maxDepth/2),i=t**+e,o=n**+e,s=t**+r,c=n**+r;this._cachedBounds={wMax:i,wMin:o,hMax:s,hMin:c,aMax:i*s,aMin:o*c}}let s=o%a.loopFrames/a.loopFrames,c=e**+Math.sin(s*Math.PI*2),l=c/(1+c);this._subdivide(i,0,0,i.width,i.height,0,!1,1,1,a,o,this._cachedBounds,l)}};export{r as SCRIPT_CONFIG};